script:
(function () {
  'use strict';
  // Market cap growth projection.
  //   Market cap in year t = cap0 × (1 + g)^t
  //   Implied revenue = market cap ÷ P/S;  implied earnings = revenue × net margin
  //   Implied P/E = market cap ÷ earnings = P/S ÷ margin; value at a comparison P/E = earnings × P/E
  // The investment is assumed to track the market cap (no dilution or buybacks): monthly growth
  // (1 + g)^(1/12) − 1, additions at the end of each month, dividends of yield/4 of the holding's
  // value paid quarterly and either reinvested or kept as cash.
  // Checks (scratchpad tests/market-cap-growth.test.js): $1B at 15% for 10 yrs = $4.0456B (closed form);
  // $10,000 at 12% for 10 yrs with no additions = $31,058.48 = 10,000 × 1.12^10; $200/month at 0% for
  // 10 yrs = $24,000 invested, $0 gain; $10,000 + $200/month at 12% for 10 yrs = $75,444.49, matching
  // 10,000 × 1.12^10 + 200 × ((1 + i)^120 − 1) / i with i = 1.12^(1/12) − 1; 4% yield reinvested at 0% growth for 1 yr = 1.01^4.
  // Fixes vs the old site: removed random "volatility" (results changed on every click), the hidden
  // 2%/yr dividend and the invented growth-linked margin; a 0 entry is no longer replaced by a default.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var big = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', notation: 'compact', maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function bigMoney(v) {
    if (Math.abs(v) < 0.005) v = 0;
    return Math.abs(v) >= 1e6 ? big.format(v) : money.format(v);
  }

  function project(o) {
    var g = o.growth / 100, margin = o.margin / 100, y = o.yieldPct / 100;
    var monthlyGrowth = Math.pow(1 + g, 1 / 12) - 1;
    var balance = o.invest, contributed = o.invest, cash = 0, rows = [];
    for (var m = 1; m <= o.years * 12; m++) {
      balance = balance * (1 + monthlyGrowth);
      if (m % 3 === 0 && y > 0) {
        var dividend = balance * y / 4;
        if (o.reinvest) balance += dividend; else cash += dividend;
      }
      balance += o.monthly;
      contributed += o.monthly;
      if (m % 12 === 0) {
        var year = m / 12, cap = o.cap * Math.pow(1 + g, year), revenue = cap / o.ps;
        rows.push({ year: year, cap: cap, revenue: revenue, earnings: revenue * margin, value: balance + cash });
      }
    }
    var last = rows[rows.length - 1];
    return { cap: last.cap, revenue: last.revenue, earnings: last.earnings, balance: balance, cash: cash,
             contributed: contributed, total: balance + cash, rows: rows };
  }

  function update() {
    var o = {
      cap: num('mcCap'), growth: num('mcGrowth'), years: Math.round(num('mcYears')), ps: num('mcPs'),
      margin: num('mcMargin'), pe: num('mcPe'), invest: num('mcInvest'), monthly: num('mcMonthly'),
      yieldPct: num('mcYield'), reinvest: document.getElementById('mcReinvest').value === 'yes'
    };
    var error = document.getElementById('mcError');
    var msg = '';
    if ([o.cap, o.growth, o.years, o.ps, o.margin, o.pe, o.invest, o.monthly, o.yieldPct].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.cap <= 0 || o.ps <= 0 || o.pe <= 0) msg = 'Market cap, price-to-sales and P/E must be greater than 0.';
    else if (o.growth < -90 || o.growth > 100) msg = 'Enter a growth rate from -90% to 100%.';
    else if (o.years < 1 || o.years > 50) msg = 'Enter 1 to 50 years.';
    else if (o.margin < -100 || o.margin > 100) msg = 'Enter a net margin from -100% to 100%.';
    else if (o.invest < 0 || o.monthly < 0) msg = 'Investment amounts cannot be negative.';
    else if (o.yieldPct < 0 || o.yieldPct > 20) msg = 'Enter a dividend yield from 0% to 20%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var r = project(o);
    document.getElementById('mcYearsOut').textContent = String(o.years);
    document.getElementById('mcFutureCap').textContent = bigMoney(r.cap);
    document.getElementById('mcMultiple').textContent = (r.cap / o.cap).toFixed(2) + '×';
    document.getElementById('mcRevenue').textContent = bigMoney(r.revenue);
    document.getElementById('mcEarnings').textContent = bigMoney(r.earnings);
    if (o.margin > 0) {
      document.getElementById('mcImpliedPe').textContent = (o.ps / (o.margin / 100)).toFixed(1) + '×';
      document.getElementById('mcAtPe').textContent = bigMoney(r.earnings * o.pe);
    } else {
      document.getElementById('mcImpliedPe').textContent = 'n/a (no profit)';
      document.getElementById('mcAtPe').textContent = 'n/a (no profit)';
    }
    var gain = r.total - r.contributed;
    document.getElementById('mcValue').textContent = money.format(r.total);
    document.getElementById('mcContributed').textContent = money.format(r.contributed);
    document.getElementById('mcGain').textContent = money.format(gain);
    document.getElementById('mcRoi').textContent = r.contributed > 0 ? (gain / r.contributed * 100).toFixed(2) + '%' : '–';
    var note = document.getElementById('mcCashNote');
    note.hidden = !(r.cash > 0);
    note.textContent = r.cash > 0 ? 'Ending value includes ' + money.format(r.cash) + ' of dividends taken as cash (not reinvested).' : '';
    document.getElementById('mcSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + bigMoney(row.cap) + '</td><td>' + bigMoney(row.revenue) + '</td><td>' +
             bigMoney(row.earnings) + '</td><td>' + money.format(row.value) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('mcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
